$("#btnRead").click(function () {
    var errorMsg = "";
    var focusFieldID = "";
    if ($("#ddlMakerName").val() == 0)
    {
        errorMsg = "Select Maker Name";
    }
    var inputfiles = document.getElementById("pdf-upload");
    const file = inputfiles.files[0];
    if (!file)
    {
        if (errorMsg == "") {
            errorMsg = "Select File";
        } else {
            errorMsg = errorMsg + "<br>" + "Select File";
        }
        if (focusFieldID == "") {
            focusFieldID = "pdf-upload";
        }

    }
    if (errorMsg != "") {
        showMessageDialog(errorMsg, focusFieldID, WARNING);
        return false;
    }
    
    var ajaxTime = new Date().getDate();
    var settings = {
        async: false,
        crossDomain: true,
        cache: false,
        processData: false,       // important for FormData
        contentType: false,      
        dataType: "json",
        url: APIURL + "/MakerMillSheet/GetMillSheetPDFDetails?makerCD=" + $("#ddlMakerName").val(),
        method: "POST",
        contentType: "application/json; charset=utf-8",
    }
    $.ajax(settings)
        .done(function (response) {
            responseTime = new Date().getTime() - ajaxTime;
           
            var result = response.message;
            if (result.length > 0)
            {
                var formData = new FormData();
                formData.append('file', file);
                formData.append('details', JSON.stringify(result));
              
                var settings = {
                    async: true,
                    crossDomain: true,
                    cache: false,
                    processData: false,       // important for FormData
                    dataType: "json",
                    url: "/MakerMillSheet/GetPDFData",
                    method: "POST",
                    contentType: false,
                    data: formData
                }
                $.ajax(settings)
                    .done(function (response) {
                        responseTime = new Date().getTime() - ajaxTime;
                        debugger;

                        var result = response.message;
                        var totalPages = response.pageCount;
                        if (totalPages > 0) {
                            pageIndex ="01";
                            $("#lblTotalPages").text(totalPages);
                            $("#lblPageIndex").text(pageIndex);
                        } else
                        {
                            $("#lblTotalPages").text(0);
                            $("#lblPageIndex").text(0);
                            
                        }
                        
                        if (result != null) {
                            arrayData = result;
                            setMillSheetDetails(0, result);
                           
                        }

                    })
                    .fail(function (xhr, textStatus, errorThrown) {
                        responseTime = new Date().getTime() - ajaxTime;
                        var errorCode = $.parseJSON(xhr.responseText).Message;

                        focusFieldID = $(':focus').attr("id");
                        message = $("#lblErrorMessageE_Maker_MillSheet_001").text().trim();
                        showMessageDialog(message, focusFieldID, ERROR);
                        return false;
                    });
            }

        })
        .fail(function (xhr, textStatus, errorThrown) {
            responseTime = new Date().getTime() - ajaxTime;
            var errorCode = $.parseJSON(xhr.responseText).Message;

            focusFieldID = $(':focus').attr("id");
            message = $("#lblErrorMessageE_Maker_MillSheet_001").text().trim();
            showMessageDialog(message, focusFieldID, ERROR);
            return false;
        });

});
$("#prev-page").click(function () {
    let i = 0;
    debugger;
    if (parseInt($("#lblPageIndex").text()) > 1 && parseInt(pageIndex) <= parseInt($("#lblTotalPages").text())) {
        pageIndex = parseInt(pageIndex) - 1;
        i = parseInt(pageIndex)-1;
        
        if (pageIndex.toString().length == 1) {
            pageIndex = "0" + pageIndex;
        }
        $("#lblPageIndex").text(pageIndex);
        setMillSheetDetails(i, arrayData)
    }

});
$("#next-page").click(function () {
    let i = 0;
    debugger;
    if (parseInt($("#lblPageIndex").text()) > 0 && parseInt(pageIndex) < parseInt($("#lblTotalPages").text()))
    {
        i = parseInt(pageIndex);
        pageIndex = parseInt(pageIndex) + 1;
       
        if (pageIndex.toString().length == 1)
        {
            pageIndex = "0" + pageIndex;
        }
        $("#lblPageIndex").text(pageIndex);
        setMillSheetDetails(i, arrayData)
    }
    
});
